class Game {
public:
  void startup(const Config& config) {
    // Loading screen: we decide exactly when and where
    audio_ = new (audioArena_.alloc(sizeof(AudioEngine)))
        AudioEngine(config.audio);
    audio_->init();  // 300ms here is invisible
  }
private:
  MemoryArena audioArena_;
  AudioEngine* audio_;
};

